def shortestCommonSupersequence(str1: str, str2: str) -> str:
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    i, j = m, n
    lcs_chars = []
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1] and dp[i][j] == dp[i - 1][j - 1] + 1:
            lcs_chars.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    lcs = ''.join(reversed(lcs_chars))

    res = []
    i = j = 0
    for char in lcs:
        while i < m and str1[i] != char:
            res.append(str1[i])
            i += 1
        while j < n and str2[j] != char:
            res.append(str2[j])
            j += 1
        if i < m and j < n:
            res.append(char)
            i += 1
            j += 1

    while i < m:
        res.append(str1[i])
        i += 1
    while j < n:
        res.append(str2[j])
        j += 1

    return ''.join(res)
